"""Generates and executes the 5 notebooks (outputs are baked in). Run from repo root: python3 build_notebooks.py"""
import nbformat as nbf
from nbclient import NotebookClient
HEAD = "import os, sys; os.chdir('..') if os.path.basename(os.getcwd())=='notebooks' else None; sys.path.insert(0,'.')\nimport warnings; warnings.filterwarnings('ignore')\nimport numpy as np, pandas as pd, joblib, matplotlib.pyplot as plt\n%matplotlib inline\n"
def nb(name, cells):
    n = nbf.v4.new_notebook(); n.cells = [nbf.v4.new_markdown_cell(c[1]) if c[0] == "m" else nbf.v4.new_code_cell(c[1]) for c in cells]
    n.metadata["kernelspec"] = dict(display_name="Python 3", language="python", name="python3")
    NotebookClient(n, timeout=600, kernel_name="python3", resources={"metadata": {"path": "notebooks"}}).execute()
    nbf.write(n, f"notebooks/{name}.ipynb"); print("built", name)

nb("01_Vintage_Analysis_&Target_Definition", [
("m", "# 01 - Roll-Rate Analysis & Target Definition\n**Data:** UCI *Default of Credit Card Clients* (30,000 Taiwanese card accounts, Apr-Sep 2005) - real data.\n\n**Scope note (honest):** the dataset is a single 6-month snapshot with no origination dates, so a true *origination-cohort vintage analysis* and a calendar *out-of-time* holdout are **not possible**. What the data does support is a real **roll-rate analysis** from 6 months of repayment status, plus a stratified train/test split."),
("c", HEAD + "from src.features import load, split, ST\ndf = load(); print(df.shape, 'default rate: %.2f%%' % (df.default.mean()*100))"),
("m", "## Roll-rate matrix (month t -> t+1), pooled over 5 monthly transitions\nPAY status: <=0 current, 1 = 1 month late (30 DPD), 2 = 60 DPD, >=3 = 90+ DPD."),
("c", "state = lambda s: np.select([s<=0, s==1, s==2], [0,1,2], default=3)\ncols = ['PAY_6','PAY_5','PAY_4','PAY_3','PAY_2','PAY_1']; L = ['Current','30 DPD','60 DPD','90+ DPD']\nM = np.zeros((4,4))\nfor a,b in zip(cols[:-1], cols[1:]):\n    sa, sb = state(df[a].values), state(df[b].values)\n    for i in range(4):\n        for j in range(4): M[i,j] += ((sa==i)&(sb==j)).sum()\nR = pd.DataFrame(M/M.sum(1,keepdims=True), index=L, columns=L); display(R.round(3))\nfor s in L[1:]: print(f'Cure rate {s:8s} -> Current next month: {R.loc[s,\"Current\"]*100:5.1f}%')\ncure90 = R.loc['90+ DPD','Current']; print('\\n90+ DPD cure rate < 10% threshold?', cure90 < 0.10)"),
("m", "## Next-month default rate by latest delinquency state"),
("c", "g = df.groupby(pd.Series(state(df.PAY_1.values), index=df.index).map(dict(enumerate(L)))).default.agg(['mean','count']).reindex(L); g['mean'] = g['mean']*100; display(g.rename(columns={'mean':'default % (next month)'}).round(1))\nshare = pd.DataFrame({c: pd.Series(state(df[c].values)).map(dict(enumerate(L))).value_counts(normalize=True) for c in cols}).reindex(L)*100\nshare.T.plot(kind='bar', stacked=True, figsize=(7,3.5), title='Portfolio delinquency mix by month (Apr -> Sep)'); plt.ylabel('% accounts'); plt.show()"),
("m", "## Target definition & sampling\nTarget = the dataset's *default payment next month* flag (1 = default). Roll rates show how sticky deep delinquency is. Sample: **stratified 70/30 split** (seed 42) preserving the 22.1% bad rate; no OOT set exists (see scope note)."),
("c", "train, test = split(df); os.makedirs('data/processed', exist_ok=True); joblib.dump((train, test), 'data/processed/split.joblib')\nprint(len(train), len(test), 'bad rate train %.4f / test %.4f' % (train.default.mean(), test.default.mean()))"),
])

nb("02_WoE_IV_Binning&Feature_Selection", [
("m", "# 02 - Monotonic WoE Binning & IV Feature Selection\n`WoE = ln(%good / %bad)`, `IV = sum((%good - %bad) * WoE)`. Rules: keep **0.02 <= IV <= 0.50**; IV > 0.50 is *flagged for leakage review* rather than silently dropped; ECOA-protected attributes (SEX, MARRIAGE) are reported but never scored."),
("c", HEAD + "from src.binning import WoEBinner\nfrom src.features import NUM, CAT, PROTECTED\ntrain, test = joblib.load('data/processed/split.joblib')\nbinners = {v: WoEBinner('num' if v in NUM else 'cat').fit(train[v].values, train.default.values) for v in NUM + CAT}\niv = pd.DataFrame({'variable': list(binners), 'IV': [b.iv_ for b in binners.values()], 'bins': [len(b.woe_) for b in binners.values()]}).sort_values('IV', ascending=False)\ndef decide(r):\n    if r.variable in PROTECTED: return 'excluded (ECOA-protected)'\n    if r.IV < 0.02: return 'drop: weak'\n    return 'review: IV>0.5' if r.IV > 0.5 else 'keep'\niv['decision'] = iv.apply(decide, axis=1); display(iv.round(4).reset_index(drop=True))"),
("m", "## Monotonicity check & example WoE profiles"),
("c", "mono = {v: bool(np.all(np.diff(b.woe_)>=0) or np.all(np.diff(b.woe_)<=0)) for v,b in binners.items() if v in NUM}\nprint('numeric variables with monotone WoE: %d / %d' % (sum(mono.values()), len(mono)))\nfig, ax = plt.subplots(1, 2, figsize=(11, 3.5))\nfor a, v in zip(ax, ['PAY_1', 'LIMIT_BAL']):\n    t = binners[v].table_; a.bar(range(len(t)), t.woe); a.set_xticks(range(len(t))); a.set_xticklabels(t.bin, rotation=45, ha='right', fontsize=7); a.set_title(f'{v} WoE (IV={binners[v].iv_:.3f})')\nplt.tight_layout(); plt.show(); display(binners['PAY_1'].table_.round(3))"),
("c", "joblib.dump(dict(binners=binners, iv=iv), 'data/processed/binning.joblib'); print('saved')"),
])

nb("03_PD_Model&Scorecard_Scaling", [
("m", "# 03 - PD Model & Scorecard Scaling\nLogistic regression on WoE features. Selection: IV filter -> collinearity filter (|r| < 0.75 on WoE) -> backward elimination until every coefficient is **negative** (higher WoE = safer) and p < 0.05.\n\nScaling: `Score = Offset + Factor * ln(odds_good)`, **600 points at 50:1 odds, PDO = 20**, clipped to 300-850."),
("c", HEAD + "import statsmodels.api as sm\nfrom src.scorecard import Scorecard\nfrom src.metrics import gini, auc, ks\ntrain, test = joblib.load('data/processed/split.joblib'); B = joblib.load('data/processed/binning.joblib'); binners, iv = B['binners'], B['iv']\ny = train.default.values\ncand = iv[iv.decision.isin(['keep', 'review: IV>0.5'])].variable.tolist()\nX = pd.DataFrame({v: binners[v].transform(train[v].values) for v in cand})\nkept = []\nfor v in cand:\n    if all(abs(np.corrcoef(X[v], X[k])[0,1]) < 0.75 for k in kept): kept.append(v)\nprint('after IV + collinearity filter:', kept)\ndef fit(vs): return sm.Logit(y, sm.add_constant(X[vs])).fit(disp=0)\ndef select(vs):\n    vs = vs[:]\n    while True:\n        m = fit(vs); bad = [v for v in vs if m.params[v] >= 0 or m.pvalues[v] > 0.05]\n        if not bad: return vs, m\n        vs.remove(max(bad, key=lambda v: m.pvalues[v]))\nvs, m = select(kept); print('final variables:', vs); display(pd.DataFrame({'coef': m.params, 'p-value': m.pvalues}).round(4))"),
("c", "sc = Scorecard(binners, {v: m.params[v] for v in vs}, m.params['const'])\nprint('Factor %.3f  Offset %.3f' % (sc.factor, sc.offset))\ns_tr, s_te = sc.score(train), sc.score(test)\nrows = []\nfor n, d, s in [('train', train, s_tr), ('test', test, s_te)]:\n    rows.append((n, auc(d.default, -s), gini(d.default, -s), ks(d.default, -s)))\nmet = pd.DataFrame(rows, columns=['sample', 'AUC', 'Gini', 'KS']).set_index('sample'); display(met.round(4))\nprint('scorecard PD vs logistic PD max abs diff: %.2e' % np.abs(sc.pd_from_score(s_tr) - m.predict(sm.add_constant(X[vs]))).max(), '(non-zero only where scores were clipped to 300-850)')"),
("m", "## Calibration by score band (test) and score distribution"),
("c", "t = test.assign(score=s_te, pd_hat=sc.pd_from_score(s_te)); t['band'] = pd.qcut(t.score, 10, duplicates='drop')\ncal = t.groupby('band').agg(accounts=('default','size'), mean_score=('score','mean'), predicted_PD=('pd_hat','mean'), observed_bad=('default','mean')); display(cal.round(3))\nplt.figure(figsize=(7,3.5)); plt.hist(t[t.default==0].score, 40, alpha=.6, label='good', density=True); plt.hist(t[t.default==1].score, 40, alpha=.6, label='bad', density=True); plt.legend(); plt.title('Score distribution (test)'); plt.show()"),
("m", "## Sensitivity: strictly applying the 'IV > 0.5 = drop' rule\nPAY_1 (latest repayment status, IV about 0.86) trips the leakage screen. It is the most recent delinquency state *before* the outcome month and is **not** derived from the target, so it is retained after review. The cost of dropping it is shown below."),
("c", "strict = [v for v in vs if iv.set_index('variable').loc[v, 'IV'] <= 0.5]\nvs2, m2 = select([v for v in kept if v in strict] + [v for v in cand if v in strict and v not in kept][:0]) if strict else ([], None)\nsc2 = Scorecard(binners, {v: m2.params[v] for v in vs2}, m2.params['const']); s2 = sc2.score(test)\nprint('strict-rule variables:', vs2); print('Test Gini  with review-retained vars: %.4f | strict IV<=0.5 rule: %.4f' % (gini(test.default, -s_te), gini(test.default, -s2)))\nsc.table.groupby('variable').points.agg(['min','max']).round(1).T"),
("c", "joblib.dump(dict(scorecard=sc, model_vars=vs, logit_params=m.params.to_dict()), 'data/processed/scorecard.joblib'); display(sc.table.head(12))"),
])

nb("04_LGD_EAD_Regulatory_Modeling", [
("m", "# 04 - LGD, EAD (CCF) & Expected Loss\n`EL = PD x LGD x EAD`.\n\n**What is real vs synthetic here:**\n- **PD** - real, from the scorecard.\n- **EAD / CCF** - estimated on *real* data using a proxy: for defaulters, the share of undrawn headroom (vs. the Jun balance, BILL_AMT4) that was drawn by Sep (BILL_AMT1).\n- **LGD** - the dataset has **no recovery data**. The two-stage LGD model is demonstrated on **clearly synthetic recoveries** generated from a known process, so we can verify the pipeline recovers the true parameters. Treat LGD values as illustrative, not as estimates for this portfolio.\n- Horizon: the dataset's default flag is **1-month-ahead**; EL is not annualised."),
("c", HEAD + "import statsmodels.api as sm\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\ntrain, test = joblib.load('data/processed/split.joblib'); art = joblib.load('data/processed/scorecard.joblib'); sc = art['scorecard']\nsig = lambda z: 1/(1+np.exp(-z))\ndef ref_util(d): return (d.BILL_AMT4.clip(lower=0) / d.LIMIT_BAL).clip(0, 1.5)\nd = train[train.default == 1]; ref = d.BILL_AMT4.clip(lower=0); room = d.LIMIT_BAL - ref; ok = room > 0.10 * d.LIMIT_BAL\nccf = ((d.BILL_AMT1.clip(lower=0) - ref) / room)[ok].clip(0.001, 0.999)\nprint('defaulters used: %d | mean CCF proxy %.3f | median %.3f' % (len(ccf), ccf.mean(), ccf.median()))\nglm = sm.GLM(ccf, sm.add_constant(ref_util(d[ok])), family=sm.families.Binomial()).fit()\nprint('CCF fractional-logit: util coef %.3f (p=%.3g), pseudo-R2 %.3f' % (glm.params.iloc[1], glm.pvalues.iloc[1], 1 - glm.deviance/glm.null_deviance))\ndef ead(d):\n    c = sig(glm.params.iloc[0] + glm.params.iloc[1]*ref_util(d)); bal = d.BILL_AMT1.clip(lower=0); return bal + c*(d.LIMIT_BAL - bal).clip(lower=0)"),
("m", "## Two-stage LGD on synthetic recoveries (known data-generating process)"),
("c", "rng = np.random.default_rng(0)\ndef feats(d): return np.c_[d.util.clip(0, 1.5), d.LIMIT_BAL / 1e6]\ndef true_p(d): f = feats(d); return sig(0.8 - 2.0*f[:,0] + 3.0*f[:,1])\ndef true_m(d):  f = feats(d); return sig(-0.2 - 0.8*f[:,0] + 2.0*f[:,1])\ndef simulate(d):\n    rec = rng.random(len(d)) < true_p(d); m = true_m(d); k = 8\n    rate = rng.beta(m*k, (1-m)*k); return np.where(rec, rate, 0.0)\ndtr = train[train.default == 1]; r = simulate(dtr); pos = r > 0\nst1 = LogisticRegression().fit(feats(dtr), pos)\nX2 = sm.add_constant(feats(dtr)[pos]); st2 = sm.GLM(np.clip(r[pos], 1e-3, 1-1e-3), X2, family=sm.families.Binomial()).fit()\nlgd_hat = lambda d: 1 - st1.predict_proba(feats(d))[:,1] * sig(sm.add_constant(feats(d), has_constant='add') @ st2.params)\nlgd_true = lambda d: 1 - true_p(d) * true_m(d)\nprint('Stage-1 AUC (any recovery): %.3f' % roc_auc_score(pos, st1.predict_proba(feats(dtr))[:,1]))\nprint('Stage-2 params est %s vs true [-0.2,-0.8,2.0]' % np.round(st2.params, 2))\nprint('LGD recovered: corr %.3f, RMSE %.3f (true mean %.3f, est mean %.3f)' % (np.corrcoef(lgd_hat(dtr), lgd_true(dtr))[0,1], np.sqrt(np.mean((lgd_hat(dtr)-lgd_true(dtr))**2)), lgd_true(dtr).mean(), lgd_hat(dtr).mean()))"),
("m", "## Expected Loss on the test portfolio"),
("c", "s = sc.score(test); t = test.assign(score=s, PD=sc.pd_from_score(s), LGD=lgd_hat(test), EAD=ead(test)); t['EL'] = t.PD * t.LGD * t.EAD\nreal = (t.default * lgd_true(test) * t.EAD).sum()\nprint('Portfolio EAD: NT$ {:,.0f}'.format(t.EAD.sum())); print('Predicted EL: NT$ {:,.0f}  ({:.2%} of EAD)'.format(t.EL.sum(), t.EL.sum()/t.EAD.sum())); print('Realised loss (actual defaults x synthetic true LGD): NT$ {:,.0f}  -> predicted/realised = {:.2f}'.format(real, t.EL.sum()/real))\nt['band'] = pd.qcut(t.score, 5, labels=['Q1 worst','Q2','Q3','Q4','Q5 best']); display(t.groupby('band').agg(accounts=('EL','size'), mean_PD=('PD','mean'), mean_LGD=('LGD','mean'), EAD=('EAD','sum'), EL=('EL','sum')).round(3))\njoblib.dump(dict(glm=glm), 'data/processed/ead_model.joblib')"),
])

nb("05_Model_Validation&_PSI_Monitoring", [
("m", "# 05 - Validation & Monitoring\nTargets: **Gini >= 0.50, AUC >= 0.75, KS >= 40%**; PSI < 0.10 stable / 0.10-0.25 review / >= 0.25 recalibrate."),
("c", HEAD + "from src.metrics import gini, auc, ks, psi, csi, psi_flag\nfrom sklearn.metrics import roc_auc_score\ntrain, test = joblib.load('data/processed/split.joblib'); art = joblib.load('data/processed/scorecard.joblib'); sc = art['scorecard']\ns_tr, s_te = sc.score(train), sc.score(test)\nT = {'Gini': (.50, gini), 'AUC': (.75, auc), 'KS': (.40, ks)}\nrows = [(m, thr, f(train.default, -s_tr), f(test.default, -s_te), 'PASS' if f(test.default, -s_te) >= thr else 'FAIL') for m, (thr, f) in T.items()]\ndisplay(pd.DataFrame(rows, columns=['metric', 'threshold', 'train', 'test', 'test status']).round(4))\nrng = np.random.default_rng(1); y = test.default.values; sv = -s_te; g = [gini(y[i], sv[i]) for i in (rng.integers(0, len(y), len(y)) for _ in range(300))]\nprint('Test Gini 95%% bootstrap CI: [%.4f, %.4f]' % tuple(np.percentile(g, [2.5, 97.5])))"),
("m", "## Stability: PSI (train vs test) and CSI per variable"),
("c", "p = psi(s_tr, s_te); print('Score PSI train->test: %.4f  -> %s' % (p, psi_flag(p)))\ncs = pd.DataFrame({'CSI': {v: csi(sc.b[v], train[v].values, test[v].values) for v in sc.points}}); display(cs.round(4))"),
("m", "## Drift simulation (SYNTHETIC shift)\nTo show the monitor firing, the test population is resampled so already-delinquent customers (PAY_1 >= 1) are 3x as likely to appear, mimicking a deteriorating intake. This is a **simulated** scenario, not observed drift."),
("c", "w = 1 + 2*(test.PAY_1 >= 1).values; idx = rng.choice(len(test), len(test), p=w / w.sum()); shift = test.iloc[idx]; s_sh = sc.score(shift)\npsh = psi(s_tr, s_sh); print('Shifted-population score PSI: %.4f -> %s' % (psh, psi_flag(psh)))\nprint('Bad rate: test %.3f -> shifted %.3f | Gini under shift %.4f' % (test.default.mean(), shift.default.mean(), gini(shift.default, -s_sh)))\npp, oo = sc.pd_from_score(s_sh).mean(), shift.default.mean(); print('Mean predicted PD under shift %.3f vs observed %.3f -> %s' % (pp, oo, 'calibration holds (pure covariate shift: P(bad|X) unchanged) - PSI flags the population change, no recalibration needed' if abs(pp-oo) < 0.02 else 'miscalibrated - recalibrate'))\ndisplay(pd.DataFrame({'CSI under shift': {v: csi(sc.b[v], train[v].values, shift[v].values) for v in sc.points}}).round(3))"),
("m", "## Decile table (test) and API check"),
("c", "t = test.assign(score=s_te); t['decile'] = pd.qcut(-t.score, 10, labels=range(1, 11)); dt = t.groupby('decile').agg(accounts=('default', 'size'), bad_rate=('default', 'mean'), min_score=('score', 'min'), max_score=('score', 'max')); dt['cum_bad_capture'] = (dt.bad_rate*dt.accounts).cumsum() / t.default.sum(); display(dt.round(3))"),
("c", "from fastapi.testclient import TestClient\nfrom src.app import app\nfrom src.features import ST, BILLS, PAYS\nc = TestClient(app); print(c.get('/health').json())\nrow = test.iloc[0]; payload = {k: float(row[k]) for k in ['LIMIT_BAL', 'AGE', 'EDUCATION'] + ST + BILLS + PAYS}\nr = c.post('/score', json=payload).json(); print(r)\nprint('API score == batch score:', r['score'] == int(round(float(sc.score(test.iloc[[0]])[0]))))"),
])
